window.WORKBOOK=[{"id": "W1I", "part": 1, "page": "21", "title": "基础Ⅰ · 单词拼写", "source": "五三 p.21 · 基础Ⅰ · 单词拼写", "kind": "fill", "questions": [{"id": "W1I-1", "number": 1, "prompt": "S___ is a football game in which two teams of 11 players try to kick or head a ball into the opponents’ goal.", "answers": ["Soccer"], "explanation": "定义对应足球 soccer；句首大写。首字母题请输入完整单词。"}, {"id": "W1I-2", "number": 2, "prompt": "She made the suggestions off her own b___, without being asked for them.", "answers": ["bat"], "explanation": "off one’s own bat 表示主动地、自发地。"}, {"id": "W1I-3", "number": 3, "prompt": "To go ___ (跳伞运动) is an adventure for me.", "answers": ["skydiving"], "explanation": "go skydiving 去跳伞；此处用活动名称。"}, {"id": "W1I-4", "number": 4, "prompt": "She has a fine pair of l___, so she can sing or shout loudly.", "answers": ["lungs"], "explanation": "a pair of 后接复数 lungs，指双肺。"}, {"id": "W1I-5", "number": 5, "prompt": "They will ___ (往往会) to model their behaviour on the teacher’s behaviour.", "answers": ["tend"], "explanation": "will 后用原形；tend to do 往往会做。"}, {"id": "W1I-6", "number": 6, "prompt": "A fatty diet increases the risk of heart d___.", "answers": ["disease"], "explanation": "heart disease 心脏病，此处为疾病类别。"}, {"id": "W1I-7", "number": 7, "prompt": "They knew the painting was a forgery. M___, they knew who had painted it.", "answers": ["Moreover"], "explanation": "补充递进信息，用 Moreover（而且）。"}, {"id": "W1I-8", "number": 8, "prompt": "We clean and repair the machines as a matter of ___ (常规，惯例).", "answers": ["routine"], "explanation": "as a matter of routine 按惯例。"}, {"id": "W1I-9", "number": 9, "prompt": "This exercise will work on the m___ of the lower back.", "answers": ["muscles"], "explanation": "下背部的肌肉，使用名词复数 muscles。"}, {"id": "W1I-10", "number": 10, "prompt": "___ (有氧的) exercise gets the heart pumping and helps you to burn fat.", "answers": ["Aerobic"], "explanation": "形容词 aerobic 修饰 exercise，句首大写。"}, {"id": "W1I-11", "number": 11, "prompt": "Are you coming for a ___ (慢跑) tomorrow morning?", "answers": ["jog"], "explanation": "a 后用单数名词；go/come for a jog。"}, {"id": "W1I-12", "number": 12, "prompt": "He survived the accident with no broken b___.", "answers": ["bones", "bone"], "explanation": "参考答案接受 bone(s)；通常用 no broken bones 表示没有骨折。"}, {"id": "W1I-13", "number": 13, "prompt": "The jeans ___ (有弹性) to provide a perfect fit.", "answers": ["stretch"], "explanation": "jeans 为复数主语，一般现在时用 stretch。"}, {"id": "W1I-14", "number": 14, "prompt": "I like volleyball and g___, which I do most of the year.", "answers": ["gymnastics"], "explanation": "gymnastics 体操，词尾 s 是词的一部分。"}, {"id": "W1I-15", "number": 15, "prompt": "Drivers in London can expect to ___ (平均为) about 12 miles per hour.", "answers": ["average"], "explanation": "expect to 后用动词原形 average，表示平均达到。"}], "passage": ""}, {"id": "W1II", "part": 1, "page": "21", "title": "基础Ⅱ · 短语填空", "source": "五三 p.21 · 基础Ⅱ · 短语填空", "kind": "fill", "questions": [{"id": "W1II-1", "number": 1, "prompt": "They formed a special group to ___ measures for labor protection.", "answers": ["work out"], "explanation": "to 后接原形；work out 制订、想出。"}, {"id": "W1II-2", "number": 2, "prompt": "They ___ the problem, hoping it will disappear of its own accord.", "answers": ["run away from"], "explanation": "run away from 在此表示逃避问题。"}, {"id": "W1II-3", "number": 3, "prompt": "His strong personality ___ his ugly appearance.", "answers": ["makes up for"], "explanation": "make up for 弥补；单数主语用 makes。"}, {"id": "W1II-4", "number": 4, "prompt": "In that respect, at least, China and India ___.", "answers": ["have something in common"], "explanation": "have something in common 有共同之处。"}, {"id": "W1II-5", "number": 5, "prompt": "Regular exercise helps the film star ___ and keep a slim figure.", "answers": ["get into shape"], "explanation": "get into shape 强身健体；helps 后可接动词原形。"}, {"id": "W1II-6", "number": 6, "prompt": "The smallest boy was unable to ___ the wall as fast as the others.", "answers": ["get over"], "explanation": "get over 越过；be unable to 后用原形。"}, {"id": "W1II-7", "number": 7, "prompt": "You just ___ me. I’ll explain everything as we go along.", "answers": ["stick with"], "explanation": "stick with 跟着、紧随；祈使表达用原形。"}, {"id": "W1II-8", "number": 8, "prompt": "Studies have shown that women ___ be more participatory in their management style.", "answers": ["tend to"], "explanation": "tend to do 往往会；主语 women 为复数。"}, {"id": "W1II-9", "number": 9, "prompt": "Genes ___ how your body balances calories and energy.", "answers": ["play a role in"], "explanation": "play a role in 在……中起作用；后接 how 从句。"}, {"id": "W1II-10", "number": 10, "prompt": "A good belly laugh can ___ for a person’s emotional state.", "answers": ["do wonders"], "explanation": "do wonders 产生奇效；can 后用原形。"}], "passage": "", "bank": "do wonders; tend to (do); stick with; make up for; run away from; have something in common; get into shape; work out; get over; play a role in"}, {"id": "W1III", "part": 1, "page": "21", "title": "基础Ⅲ · 单句语法填空", "source": "五三 p.21 · 基础Ⅲ · 单句语法填空", "kind": "fill", "questions": [{"id": "W1III-1", "number": 1, "prompt": "You’ve passed your driving test? ___ (congratulate)!", "answers": ["Congratulations"], "explanation": "祝贺时常用名词复数 Congratulations。"}, {"id": "W1III-2", "number": 2, "prompt": "We are working on the ___ (assume) that everyone invited will turn up.", "answers": ["assumption"], "explanation": "the 后用名词 assumption；on the assumption that 在……假定下。"}, {"id": "W1III-3", "number": 3, "prompt": "He knew I was ___ (energy) and dynamic and would get things done.", "answers": ["energetic"], "explanation": "与 dynamic 并列作表语，用形容词 energetic。"}, {"id": "W1III-4", "number": 4, "prompt": "In the crash he sustained severe ___ (injure) to the head and arms.", "answers": ["injuries"], "explanation": "severe 修饰名词；头部和手臂多处受伤，用复数 injuries。"}, {"id": "W1III-5", "number": 5, "prompt": "You know what they say, ___ (prevent) is better than cure.", "answers": ["prevention"], "explanation": "作主语用名词 prevention，通常不可数。"}, {"id": "W1III-6", "number": 6, "prompt": "This ___ (equip) has saved the lives of a number of new born babies.", "answers": ["equipment"], "explanation": "equipment 为不可数名词，不加 s。"}, {"id": "W1III-7", "number": 7, "prompt": "The book is completely ___ (lack) in originality.", "answers": ["lacking"], "explanation": "be lacking in 缺乏；形容词作表语。"}, {"id": "W1III-8", "number": 8, "prompt": "The house is large and difficult ___ (maintain).", "answers": ["to maintain"], "explanation": "主语＋be＋形容词＋to do，主动形式表达被动含义。"}, {"id": "W1III-9", "number": 9, "prompt": "Walking is extremely ___ (benefit) to your body shape.", "answers": ["beneficial"], "explanation": "be beneficial to 对……有益。"}, {"id": "W1III-10", "number": 10, "prompt": "We are looking at our business to see where savings and ___ (efficient) can be made.", "answers": ["efficiencies"], "explanation": "与 savings 并列作主语；efficiency 表提高效率的方法时可数，此处用复数。"}], "passage": ""}, {"id": "W1IV", "part": 1, "page": "22", "title": "基础Ⅳ · 完成句子", "source": "五三 p.22 · 基础Ⅳ · 完成句子", "kind": "fill", "questions": [{"id": "W1IV-1", "number": 1, "prompt": "科罗拉多大峡谷是世界自然奇观之一。The Grand Canyon ___ of the world.", "answers": ["is one of the natural wonders"], "explanation": "one of＋复数名词；natural wonders 自然奇观。"}, {"id": "W1IV-2", "number": 2, "prompt": "在我们的文化中，我们往往羞于谈论自己的才干和技能。In our culture we ___ be shy about our talents and skills.", "answers": ["tend to"], "explanation": "tend to be 往往会；主语 we 用原形。"}, {"id": "W1IV-3", "number": 3, "prompt": "那些话将伴随我的余生。Those words will ___ me for the rest of my life.", "answers": ["stick with"], "explanation": "stick with 在此表示留在记忆中、伴随。"}, {"id": "W1IV-4", "number": 4, "prompt": "你此刻的善良举止弥补了你上周的粗鲁。Your kind behavior now ___ your rudeness last week.", "answers": ["makes up for"], "explanation": "主语 behavior 不可数，谓语用 makes。"}, {"id": "W1IV-5", "number": 5, "prompt": "他不能逃避自己的责任。He can’t ___ his responsibility.", "answers": ["run away from"], "explanation": "can’t 后用原形；run away from 逃避。"}, {"id": "W1IV-6", "number": 6, "prompt": "你和他有共同之处。You and he ___.", "answers": ["have something in common"], "explanation": "并列主语 You and he 用 have。"}, {"id": "W1IV-7", "number": 7, "prompt": "我下定决心要减肥，最终强身健体。I make a resolution to lose weight and finally ___.", "answers": ["get into shape"], "explanation": "与 lose weight 并列，用动词原形。"}, {"id": "W1IV-8", "number": 8, "prompt": "长远来看，这样的措施可能会使事情更糟。___, such measures may make the things worse.", "answers": ["Over the long term"], "explanation": "over the long term 从长远来看。"}, {"id": "W1IV-9", "number": 9, "prompt": "我肯定这会对我们的自然环境造成影响。I am sure that it will ___ our natural environment.", "answers": ["have an effect on"], "explanation": "have an effect on 对……产生影响。"}, {"id": "W1IV-10", "number": 10, "prompt": "我至少有一周没看见他了。I have not seen him for ___ a week.", "answers": ["at least"], "explanation": "at least 至少，与时间长度连用。"}], "passage": ""}, {"id": "W1V", "part": 1, "page": "22", "title": "基础Ⅴ · 翻译句子", "source": "五三 p.22 · 基础Ⅴ · 翻译句子", "kind": "manual", "questions": [{"id": "W1V-1", "number": 1, "prompt": "耐心和毅力可产生奇效。(do wonders)", "answers": ["Patience and perseverance will do wonders."], "explanation": "并列名词作主语；do wonders 表产生奇效，will 表可能的结果。"}, {"id": "W1V-2", "number": 2, "prompt": "如果你坚持下去，你的演奏会逐渐变好。(stick with)", "answers": ["If you stick with it, your playing will gradually get better."], "explanation": "if 条件从句一般现在时，主句一般将来时；playing 为名词性用法。"}, {"id": "W1V-3", "number": 3, "prompt": "勤奋工作经常可以弥补智力的不足。(make up for)", "answers": ["Hard work can often make up for a lack of intelligence."], "explanation": "make up for 弥补；a lack of 缺乏。"}, {"id": "W1V-4", "number": 4, "prompt": "你无法避免冲突，但它们是可以被控制的。(run away from)", "answers": ["You can’t run away from conflicts but they can be managed."], "explanation": "前句主动，后句 can be managed 为情态动词被动语态。"}, {"id": "W1V-5", "number": 5, "prompt": "因为有共同之处，所以我们互相吸引对方。(have something in common)", "answers": ["We are attracted by each other, because we have something in common."], "explanation": "because 引导原因；be attracted by 被……吸引。"}, {"id": "W1V-6", "number": 6, "prompt": "我们必须尽快想出一个大家都能接受的计划。(work out)", "answers": ["We must work out a plan acceptable to all as quickly as we can."], "explanation": "acceptable to all 作后置定语；as quickly as we can 尽快。"}, {"id": "W1V-7", "number": 7, "prompt": "我们必须克服我们前进道路上的困难。(get over)", "answers": ["We must get over the difficulties on our way forward."], "explanation": "get over 克服；on our way forward 在前进道路上。"}, {"id": "W1V-8", "number": 8, "prompt": "他被邀请在这部电视剧里扮演一个角色。(play a role in)", "answers": ["He was invited to play a role in this TV play."], "explanation": "was invited to do 被邀请做；play a role in 扮演角色。"}, {"id": "W1V-9", "number": 9, "prompt": "事实证明，穿特定颜色的衣服会影响我们的情绪。(that 引导主语从句)", "answers": ["It has been proved that wearing clothes of a particular color can affect our mood."], "explanation": "It 为形式主语；that 引导主语从句；proved/proven 均可；wearing 短语作从句主语。"}, {"id": "W1V-10", "number": 10, "prompt": "我认为首先需要考虑的事情是文化差异。(动词不定式作后置定语)", "answers": ["I think the first thing to consider is cultural differences."], "explanation": "to consider 后置修饰 the first thing；think 后省略 that。"}], "passage": ""}, {"id": "W1VI", "part": 1, "page": "22", "title": "基础Ⅵ · 课文语法填空", "source": "五三 p.22 · 基础Ⅵ · 课文语法填空", "kind": "fill", "questions": [{"id": "W1VI-1", "number": 1, "prompt": "第1空", "answers": ["and"], "explanation": "祈使句＋and＋陈述句，表示做某事就会出现后面的结果。"}, {"id": "W1VI-2", "number": 2, "prompt": "第2空 (benefit)", "answers": ["beneficial"], "explanation": "be beneficial to；形容词作表语。"}, {"id": "W1VI-3", "number": 3, "prompt": "第3空 (lung)", "answers": ["lungs"], "explanation": "人的双肺，用可数名词复数。"}, {"id": "W1VI-4", "number": 4, "prompt": "第4空", "answers": ["of"], "explanation": "at risk of 有……风险。"}, {"id": "W1VI-5", "number": 5, "prompt": "第5空 (increase)", "answers": ["increases"], "explanation": "Strength training 作单数主语，一般现在时谓语加 s。"}, {"id": "W1VI-6", "number": 6, "prompt": "第6空 (move)", "answers": ["movement"], "explanation": "range of movement 活动范围；介词后用名词。"}, {"id": "W1VI-7", "number": 7, "prompt": "第7空", "answers": ["in"], "explanation": "be rich in 富含。"}, {"id": "W1VI-8", "number": 8, "prompt": "第8空", "answers": ["for"], "explanation": "make up for 弥补。"}, {"id": "W1VI-9", "number": 9, "prompt": "第9空 (equip)", "answers": ["equipment"], "explanation": "与 clothes 并列用名词；equipment 不可数。"}, {"id": "W1VI-10", "number": 10, "prompt": "第10空 (exercise)", "answers": ["exercising"], "explanation": "before 作介词，后接动名词。"}], "passage": "Start exercise, [1] you will take your first step towards a new and improved you! Regular exercise is [2] (benefit) to your body and mind. Physical activity increases the efficiency of your heart and [3] (lung). It is certain that active people tend to have better immune systems and are at a lower risk [4] diseases.\n\nPlanning your exercise routine is necessary. Aerobic activities can develop your heart and lungs. Strength training [5] (increase) muscle strength and encourages bone development. Flexibility training helps stretch your muscles and improve your body’s range of [6] (move).\n\nEat and drink right and you will keep up your energy during a long workout. You are supposed to eat foods rich [7] protein. Do not eat immediately after exercise. Remember to drink throughout exercise to make up [8] water lost to sweat.\n\nWear proper clothes and [9] (equip) when exercising. In addition, you should start small and slowly work your way to a longer and harder exercise routine. Finally, remember to warm up before [10] (exercise) and stretch at the end of your workout. Only in these ways can you avoid injury."}, {"id": "W1A", "part": 1, "page": "23", "title": "提升Ⅰ · 阅读理解 A", "source": "五三 p.23 · 提升Ⅰ · 阅读理解 A", "kind": "choice", "questions": [{"id": "W1A-1", "number": 1, "prompt": "What does the underlined word “it” in Paragraph 2 refer to?", "answers": ["B"], "explanation": "前文讨论 the way you breathe，后文用鼻还是用嘴呼吸进行解释，因此 it 指呼吸方式。", "options": ["Your life style.", "How you breathe.", "How you think and feel.", "The oxygen you take in."]}, {"id": "W1A-2", "number": 2, "prompt": "What did Swedish researchers find?", "answers": ["A"], "explanation": "第三段指出用鼻子呼吸的人更能记住闻过的气味，故选改善记忆。", "options": ["Nose breathing may improve memory.", "Mouth breathing causes health problems.", "Nose breathers are not sensitive to smells.", "Mouth breathers have a good sense of taste."]}, {"id": "W1A-3", "number": 3, "prompt": "What is the effect of nose breathing according to the research in Paragraph 4?", "answers": ["C"], "explanation": "第四段末句说鼻呼吸时大脑活动出现更多变化，选 C；没有说能治愈口臭或打鼾。", "options": ["It helps one to stay healthy.", "It cures bad breath and snoring.", "It makes one’s brain more active.", "It improves one’s sense of smell."]}, {"id": "W1A-4", "number": 4, "prompt": "What does the author think of nose breathing?", "answers": ["D"], "explanation": "末段说这种习惯可能帮人应对紧急情况，表达其益处；并非要求所有人改变。", "options": ["It’s hard to get used to.", "It’s suitable for everybody.", "It’s what people have to do.", "It’s what people can benefit from."]}], "passage": "Breathing is something you do all day long, without even thinking about it. However, you might be doing it wrong. Research shows that the way you breathe affects the amount of oxygen you take in, as well as how you think and feel.\n\nSo which is it? Do you breathe through your nose or your mouth? Some health experts recommend people breathe in through their nose and out through their mouth. Others say that people should just focus on breathing easily, paying no attention to their mouth or nose preference. But mouth breathing has also been connected with bad breath, snoring (打呼噜), high blood pressure and bad teeth.\n\nNose breathing may affect how memories are stabilized (稳定) in our brains, according to Swedish researchers. During their study, participants smelled 12 different smells and then were asked to breathe either through their nose or mouth for an hour afterwards. Then, they were presented with the original set of smells and a new set. Those who smelled with their nose remembered the smells better.\n\nA research team recognized the differences in brain activity that occurred when seven epilepsy (癫痫) patients breathed through their nose or through their mouth. The team found three areas of the brain where activity is connected with breathing. These areas showed more changes in brain activity only when volunteers breathed through their nose.\n\nSo, should mouth breathers change their breathing habits? If you’re happy with the way you breathe and if you aren’t experiencing any health problems, be yourself and just keep your own way. But if you think it might be time for a change, focus on breathing through your nose until it becomes a habit. It might help you survive an emergency.", "marks": ["it"]}, {"id": "W1B", "part": 1, "page": "23—24", "title": "提升Ⅰ · 阅读理解 B", "source": "五三 p.23—24 · 提升Ⅰ · 阅读理解 B", "kind": "choice", "questions": [{"id": "W1B-5", "number": 5, "prompt": "What do most students of Lochaber High School do after graduating?", "answers": ["B"], "explanation": "第二段说 most students 继续深造，对应进入大学；不能据少数人的去向推断全体。", "options": ["Go abroad.", "Enter colleges.", "Go to work.", "Stay at Lochaber."]}, {"id": "W1B-6", "number": 6, "prompt": "Why do many young people of Lochaber leave their hometown?", "answers": ["C"], "explanation": "第二段明确说当地 opportunities 不够，因此离乡寻找更多机会。", "options": ["To meet their old friends.", "To live a more peaceful life.", "To find more opportunities.", "To escape from reality."]}, {"id": "W1B-7", "number": 7, "prompt": "What is the last paragraph mainly about?", "answers": ["C"], "explanation": "全段概括社区关系、丰富活动与好客氛围，C 最全面；B、D 仅为局部细节。", "options": ["The boring life in Fort William.", "The communities of Fort William.", "The nice living atmosphere of Fort William.", "Something to do or to see in Fort William."]}, {"id": "W1B-8", "number": 8, "prompt": "Which of the following best explains “hospitality” underlined in Paragraph 3?", "answers": ["B"], "explanation": "后文 People look forward to seeing you 提示欢迎来客，hospitality 指热情好客。", "options": ["The quality of being honest.", "Friendly behavior towards guests.", "Trust based on much experience.", "Unfair and often painful feeling."]}], "passage": "With 830 students aged between 8 and 12, Lochaber High School, in Fort William, is one of the largest secondary schools in the Highlands. It covers a huge area and many of the students come from small communities and travel up to 40 km to get to school every day. In the past, the school covered a much larger area and many students had to stay in one of the school dormitories, or if older to live with local families, but other high schools have opened in the West Highlands, so the catchment area (招生区域) for Lochaber, though still very large, is not as large as it used to be. Students travel to school by car, by bus, or by special minibus every day, and some go on foot or by bike. Most students just live in Fort William, or in one of the surrounding villages.\n\nAt the end of their high school life, and after getting higher or advanced higher grade exam results, most students decide to move on to further their education. Some students can remain, taking specialised courses at the West Highland College, but many leave their homes in Lochaber and go south or east to other cities. Many young people in this area feel that there are not enough opportunities here. Going to a city certainly means new friends, a whole new lifestyle, and a more exciting night life.\n\nEven though Fort William is, in a way, small and far away from cities, as far as I am concerned, it is a great place to live. There is a real community atmosphere (氛围) here, and many people know, or are related to, many other people. There is always something to do or to see in Fort William and there is no excuse for being bored! But there is one thing that is certain for everyone, that is, Highland hospitality. It is still very real, very alive! People look forward to seeing you!", "marks": ["hospitality"]}, {"id": "W1GAP", "part": 1, "page": "24", "title": "提升Ⅱ · 七选五", "source": "五三 p.24 · 提升Ⅱ · 七选五", "kind": "gap", "questions": [{"id": "W1GAP-1", "number": 1, "prompt": "第1空", "answers": ["A"], "explanation": "前文躲开咳嗽者、洗手说明作者重视流感，A 总结并引出流感季主题。", "options": ["Flu season is here, and I take it seriously.", "If you got the flu shot last year, do you need it this year?", "Each year more than 200,000 people are staying in hospital due to the illness.", "If you have the symptoms, call your doctor early to see if he wants to prescribe some medicine.", "Flu symptoms usually come on suddenly and frequently include high fever, cough, sore throat and body ache.", "Often doctors’ offices have special rooms set up just for giving flu shots, so it’s fast, easy and effective.", "A new study found that the flu vaccine didn’t work as well as we thought or would like."]}, {"id": "W1GAP-2", "number": 2, "prompt": "第2空", "answers": ["C"], "explanation": "后句说明死亡人数；C 的住院人数承接上文高风险群体并递进呈现危害。", "options": ["Flu season is here, and I take it seriously.", "If you got the flu shot last year, do you need it this year?", "Each year more than 200,000 people are staying in hospital due to the illness.", "If you have the symptoms, call your doctor early to see if he wants to prescribe some medicine.", "Flu symptoms usually come on suddenly and frequently include high fever, cough, sore throat and body ache.", "Often doctors’ offices have special rooms set up just for giving flu shots, so it’s fast, easy and effective.", "A new study found that the flu vaccine didn’t work as well as we thought or would like."]}, {"id": "W1GAP-3", "number": 3, "prompt": "第3空", "answers": ["G"], "explanation": "后句 However 转折说疫苗仍有保护作用，因此空处应谈疫苗效果不如预期。", "options": ["Flu season is here, and I take it seriously.", "If you got the flu shot last year, do you need it this year?", "Each year more than 200,000 people are staying in hospital due to the illness.", "If you have the symptoms, call your doctor early to see if he wants to prescribe some medicine.", "Flu symptoms usually come on suddenly and frequently include high fever, cough, sore throat and body ache.", "Often doctors’ offices have special rooms set up just for giving flu shots, so it’s fast, easy and effective.", "A new study found that the flu vaccine didn’t work as well as we thought or would like."]}, {"id": "W1GAP-4", "number": 4, "prompt": "第4空", "answers": ["B"], "explanation": "后文讨论保护时长和是否只管一年，B 提问去年接种后今年是否还需要。", "options": ["Flu season is here, and I take it seriously.", "If you got the flu shot last year, do you need it this year?", "Each year more than 200,000 people are staying in hospital due to the illness.", "If you have the symptoms, call your doctor early to see if he wants to prescribe some medicine.", "Flu symptoms usually come on suddenly and frequently include high fever, cough, sore throat and body ache.", "Often doctors’ offices have special rooms set up just for giving flu shots, so it’s fast, easy and effective.", "A new study found that the flu vaccine didn’t work as well as we thought or would like."]}, {"id": "W1GAP-5", "number": 5, "prompt": "第5空", "answers": ["D"], "explanation": "位于患流感后的建议列表中，D 的及早联系医生符合此段功能。", "options": ["Flu season is here, and I take it seriously.", "If you got the flu shot last year, do you need it this year?", "Each year more than 200,000 people are staying in hospital due to the illness.", "If you have the symptoms, call your doctor early to see if he wants to prescribe some medicine.", "Flu symptoms usually come on suddenly and frequently include high fever, cough, sore throat and body ache.", "Often doctors’ offices have special rooms set up just for giving flu shots, so it’s fast, easy and effective.", "A new study found that the flu vaccine didn’t work as well as we thought or would like."]}], "passage": "Top Tips for the Flu Season\n\nIt’s coming. I can feel it in the air. On the subway every time someone coughs, I look up to see if I can move a little further. As I get off the train, I immediately wash my hands to remove any of the dirt on them. [1]\n\nIf you are young and healthy, it’s most likely that you will just feel uncomfortable for a week or two and miss some work or study. If you are elderly, have medical problems, or are a young child, you may not be so lucky. [2] Depending on the year, between 3,000 and 49,000 people die.\n\nThe best way to prevent the flu is to get vaccinated (接种疫苗). [3] However, it still offers considerable protection. In adults, the vaccine is 59% protective on average. For children the effect is better. Clearly, we need better vaccines but it’s still a really good idea to get vaccinated.\n\nCan the flu injection (注射) give you the flu? You may have an arm pain or a little fever, but the injection does not contain a live virus and cannot give you the flu.\n\n[4] It isn’t clear how long the protection lasts and if the vaccine protects against different flus for only one year.\n\nFinally, here is some advice on what to do if you get the flu.\n• [5]\n• Stay at home until your fever has been gone for at least 24 hours. That will reduce the number of people you give this to.\n• Cover your coughs and sneezes.\n• Keep your hands clean. Use soap and water to wash your hands frequently, especially after coughing or sneezing.\n• Drink plenty of water.\nBest wishes for a happy flu season!", "bank": ["Flu season is here, and I take it seriously.", "If you got the flu shot last year, do you need it this year?", "Each year more than 200,000 people are staying in hospital due to the illness.", "If you have the symptoms, call your doctor early to see if he wants to prescribe some medicine.", "Flu symptoms usually come on suddenly and frequently include high fever, cough, sore throat and body ache.", "Often doctors’ offices have special rooms set up just for giving flu shots, so it’s fast, easy and effective.", "A new study found that the flu vaccine didn’t work as well as we thought or would like."]}, {"id": "W2I", "part": 2, "page": "25", "title": "基础Ⅰ · 单词拼写", "source": "五三 p.25 · 基础Ⅰ · 单词拼写", "kind": "fill", "questions": [{"id": "W2I-1", "number": 1, "prompt": "The hotel has special f___ for welcoming disabled people.", "answers": ["facilities"], "explanation": "special 修饰复数名词 facilities（设施）。"}, {"id": "W2I-2", "number": 2, "prompt": "It’s about time we ___ (更新) our software.", "answers": ["updated"], "explanation": "It’s about time 后从句用过去式表示现在该做而未做的事。"}, {"id": "W2I-3", "number": 3, "prompt": "These measures in no way r___ the need for regular safety checks.", "answers": ["replace"], "explanation": "主语 measures 为复数；replace 取代。"}, {"id": "W2I-4", "number": 4, "prompt": "Some speakers argued that ___ (拳击运动) was less dangerous than rugby.", "answers": ["boxing"], "explanation": "运动名词 boxing 作主语。"}, {"id": "W2I-5", "number": 5, "prompt": "They took their landlord to c___ for breaking the contract.", "answers": ["court"], "explanation": "take sb. to court 起诉某人。"}, {"id": "W2I-6", "number": 6, "prompt": "We’ve got to fit five people ___ (加；和) all their luggage in the car.", "answers": ["plus"], "explanation": "plus 连接额外加入的人或物。"}, {"id": "W2I-7", "number": 7, "prompt": "He might easily have been seen by someone who lived n___.", "answers": ["nearby"], "explanation": "nearby 副词，修饰 lived。"}, {"id": "W2I-8", "number": 8, "prompt": "Take your ___ (同伴；伙伴) for the next dance.", "answers": ["partner", "partners"], "explanation": "参考答案接受 partner(s)；指舞伴。"}, {"id": "W2I-9", "number": 9, "prompt": "From his p___ on the cliff top, he had a good view of the harbour.", "answers": ["position"], "explanation": "his 后接名词，position 表位置。"}, {"id": "W2I-10", "number": 10, "prompt": "They were weakened by a diet that was low in ___ (蛋白质).", "answers": ["protein"], "explanation": "be low in protein 蛋白质含量低。"}, {"id": "W2I-11", "number": 11, "prompt": "The price of p___ has come down by four pence a gallon.", "answers": ["petrol"], "explanation": "按加仑计价的汽油 petrol，不可数。"}, {"id": "W2I-12", "number": 12, "prompt": "She completed the routine without even working up a ___ (汗水).", "answers": ["sweat"], "explanation": "work up a sweat 出汗，为习惯表达。"}, {"id": "W2I-13", "number": 13, "prompt": "You’ll eventually become ___ (不受影响的) to criticism.", "answers": ["immune"], "explanation": "become immune to 不受……影响。"}, {"id": "W2I-14", "number": 14, "prompt": "The museum is open daily ___ (自始至终) the year.", "answers": ["throughout"], "explanation": "throughout the year 全年。"}, {"id": "W2I-15", "number": 15, "prompt": "It is easier to p___ something from happening than to undo the damage or cure the disease later.", "answers": ["prevent"], "explanation": "prevent ... from doing 阻止……发生。"}], "passage": ""}, {"id": "W2II", "part": 2, "page": "25", "title": "基础Ⅱ · 短语填空", "source": "五三 p.25 · 基础Ⅱ · 短语填空", "kind": "fill", "questions": [{"id": "W2II-1", "number": 1, "prompt": "The dog lay in the shade with his tongue ___; it was so hot.", "answers": ["hanging out"], "explanation": "with＋名词＋现在分词；舌头与 hang out 为主动关系。"}, {"id": "W2II-2", "number": 2, "prompt": "You can ___ activities from canoeing to bird watching.", "answers": ["take part in"], "explanation": "can 后接原形；take part in 参加活动。"}, {"id": "W2II-3", "number": 3, "prompt": "His father was ___ last week, but he’s all right now.", "answers": ["under the weather"], "explanation": "under the weather 身体不适，作表语。"}, {"id": "W2II-4", "number": 4, "prompt": "It was some time before the door opened ___ his ring.", "answers": ["in response to"], "explanation": "in response to 对……作出反应。"}, {"id": "W2II-5", "number": 5, "prompt": "This latest incident will ___ the pressure on the government.", "answers": ["add to"], "explanation": "add to 增加，will 后接原形。"}, {"id": "W2II-6", "number": 6, "prompt": "The accountant ___ the bills and found them OK.", "answers": ["checked out"], "explanation": "与 found 并列，使用过去式；check out 核查。"}, {"id": "W2II-7", "number": 7, "prompt": "The exchange rate is likely to fall ___.", "answers": ["in the near future"], "explanation": "in the near future 在不久的将来。"}, {"id": "W2II-8", "number": 8, "prompt": "___ your child’s toys and then categorise them as sociable or antisocial.", "answers": ["Make a list of"], "explanation": "祈使句用原形；make a list of 列清单。"}, {"id": "W2II-9", "number": 9, "prompt": "___, it is one of the worst books I’ve ever read.", "answers": ["To be honest"], "explanation": "独立插入语，意为说实话。"}, {"id": "W2II-10", "number": 10, "prompt": "Everyone should ___ the impact of information technology on future life.", "answers": ["be concerned about"], "explanation": "should 后接 be；关心、关注某事。"}, {"id": "W2II-11", "number": 11, "prompt": "Make sure you have ample time to ___ the new day ahead.", "answers": ["make preparations for"], "explanation": "make preparations for 为……作准备。"}, {"id": "W2II-12", "number": 12, "prompt": "He saw the song’s potential, and persuaded the company to ___ her ___.", "answers": ["sign; up"], "explanation": "sign sb. up 签约、招募；两个空依次填 sign 和 up。", "fields": ["sign", "up"]}, {"id": "W2II-13", "number": 13, "prompt": "The restrictions have been ___, after a five-day national strike.", "answers": ["put in place"], "explanation": "现在完成时被动；put 的过去分词仍是 put。"}, {"id": "W2II-14", "number": 14, "prompt": "Were you ___, you would understand me.", "answers": ["in my position"], "explanation": "虚拟条件句省略 if 并倒装；in my position 处于我的处境。"}, {"id": "W2II-15", "number": 15, "prompt": "After he returned to his home in San Francisco, he quit his band to ___ the work he’d started on vacation.", "answers": ["put finishing touches to"], "explanation": "to 后接原形；put finishing touches to 作最后润色。"}], "passage": "", "bank": "put finishing touches to; in response to; under the weather; check out; add to; make preparations for; put in place; in the near future; make a list of; to be honest; take part in; hang out; be concerned about; sign (sb.) up; in one’s position"}, {"id": "W2III", "part": 2, "page": "25—26", "title": "基础Ⅲ · 单句语法填空", "source": "五三 p.25—26 · 基础Ⅲ · 单句语法填空", "kind": "fill", "questions": [{"id": "W2III-1", "number": 1, "prompt": "Today’s ___ (announce) of a peace agreement comes after weeks of discussion.", "answers": ["announcement"], "explanation": "名词所有格后接名词 announcement。"}, {"id": "W2III-2", "number": 2, "prompt": "We assume that emotions arise in response ___ what others do or say to us.", "answers": ["to"], "explanation": "in response to 固定搭配，to 为介词。"}, {"id": "W2III-3", "number": 3, "prompt": "I detected a slight ___ (move) in the undergrowth.", "answers": ["movement"], "explanation": "a slight 后接单数名词 movement。"}, {"id": "W2III-4", "number": 4, "prompt": "Reading will ___ (large) your vocabulary.", "answers": ["enlarge"], "explanation": "will 后需动词原形；large → enlarge 扩大。"}, {"id": "W2III-5", "number": 5, "prompt": "How did you come ___ that beautiful landscape painting?", "answers": ["by"], "explanation": "come by 获得、弄到。"}, {"id": "W2III-6", "number": 6, "prompt": "The school gym ___ (build) now.", "answers": ["is being built"], "explanation": "now 表进行；gym 承受建造动作，单数主语用 is being built。"}, {"id": "W2III-7", "number": 7, "prompt": "Pale wooden floors and plenty of natural light add ___ the relaxed atmosphere.", "answers": ["to"], "explanation": "add to 增添。"}, {"id": "W2III-8", "number": 8, "prompt": "I’m going to prepare ___ tomorrow’s lessons.", "answers": ["for"], "explanation": "prepare for 为……准备。"}, {"id": "W2III-9", "number": 9, "prompt": "We lacked ___ (concentrate) and it cost us the goal and the game.", "answers": ["concentration"], "explanation": "作 lacked 的宾语，用名词 concentration。"}, {"id": "W2III-10", "number": 10, "prompt": "___ (express) of sympathy flooded in from all over the country.", "answers": ["Expressions"], "explanation": "此处指多种同情表达，用复数名词作主语。"}, {"id": "W2III-11", "number": 11, "prompt": "I’d like to hear your ___ (suggest) for ways of raising money.", "answers": ["suggestions"], "explanation": "your 后接名词；多条建议用复数 suggestions。"}, {"id": "W2III-12", "number": 12, "prompt": "The plant comes with full ___ (instruct) on how to care for it.", "answers": ["instructions"], "explanation": "说明、用法常用 instructions 复数形式。"}, {"id": "W2III-13", "number": 13, "prompt": "The sports meeting ___ (put) off until next Friday.", "answers": ["has been put"], "explanation": "强调已经作出的延期安排；meeting 承受动作，用现在完成时被动。"}], "passage": ""}, {"id": "W2IV", "part": 2, "page": "26", "title": "基础Ⅳ · 完成句子", "source": "五三 p.26 · 基础Ⅳ · 完成句子", "kind": "fill", "questions": [{"id": "W2IV-1", "number": 1, "prompt": "这种产品是为了响应顾客的需要而开发的。The product was developed ___ customer demand.", "answers": ["in response to"], "explanation": "in response to 响应。"}, {"id": "W2IV-2", "number": 2, "prompt": "布赖恩不舒服，因此他早早就去睡觉了。Brian felt ___, so he went to bed early.", "answers": ["under the weather"], "explanation": "feel under the weather 感到身体不适。"}, {"id": "W2IV-3", "number": 3, "prompt": "我们结账离开旅馆以后，就直接去飞机场了。We headed directly for the airport after we had ___ of the hotel.", "answers": ["checked out"], "explanation": "had 后用过去分词；check out of the hotel 退房。"}, {"id": "W2IV-4", "number": 4, "prompt": "我本想和你一起去，但我不得不准备一场考试。I would like to have gone with you but I had to ___.", "answers": ["prepare for an exam"], "explanation": "had to 后接原形；prepare for an exam 备考。"}, {"id": "W2IV-5", "number": 5, "prompt": "针对该问题还将出台更多政策和措施。More policies and measures will be ___ in this regard.", "answers": ["put in place"], "explanation": "will be＋过去分词；put in place 实施、落实。"}, {"id": "W2IV-6", "number": 6, "prompt": "现在几条新路线正在修建，在不久的将来就会完成。Several new lines ___ now and will be completed ___.", "answers": ["are being built; in the near future"], "explanation": "第一空现在进行时被动，主语 lines 复数；第二空是时间短语。", "fields": ["are being built", "in the near future"]}, {"id": "W2IV-7", "number": 7, "prompt": "大家提的问题我还没来得及列出清单。I haven’t had time yet to ___ everyone’s questions.", "answers": ["make a list of"], "explanation": "make a list of 列出……清单。"}, {"id": "W2IV-8", "number": 8, "prompt": "说实话，他太好强了。___, he is too aggressive.", "answers": ["To be honest"], "explanation": "插入语 To be honest，首词大写。"}, {"id": "W2IV-9", "number": 9, "prompt": "参加这项运动不需要花费你太多体力。You don’t need much strength ___ this sport.", "answers": ["to take part in"], "explanation": "不定式表用途；take part in 参加。"}, {"id": "W2IV-10", "number": 10, "prompt": "他们决定继续执行原来的计划。They decided to ___ their original plan.", "answers": ["stick with"], "explanation": "decide to do；stick with 坚持、不放弃。"}], "passage": ""}, {"id": "W2V", "part": 2, "page": "26", "title": "基础Ⅴ · 翻译句子", "source": "五三 p.26 · 基础Ⅴ · 翻译句子", "kind": "manual", "questions": [{"id": "W2V-1", "number": 1, "prompt": "她把所写的东西又看了一遍，并对文章进行了最后的润色。(put finishing touches to)", "answers": ["She went over what she had written and put finishing touches to the essay."], "explanation": "what 引导宾语从句；had written 先于 went over；put 与 went 并列为过去式。"}, {"id": "W2V-2", "number": 2, "prompt": "迫于公众压力，这部法律得以通过。(in response to)", "answers": ["The law was passed in response to public pressure."], "explanation": "法律被通过，用 was passed；in response to 响应。"}, {"id": "W2V-3", "number": 3, "prompt": "我上星期身体有点不舒服，但现在好多了。(under the weather)", "answers": ["I was a bit under the weather last week, but I’m much better now."], "explanation": "last week 用 was，now 用 am；much 修饰比较级 better。"}, {"id": "W2V-4", "number": 4, "prompt": "客人必须在中午前结账离开，否则将付全日费用。(check out)", "answers": ["Guests must check out before noon, or they will be charged for the day."], "explanation": "or 表否则；will be charged 为将来时被动。"}, {"id": "W2V-5", "number": 5, "prompt": "我不想给你添麻烦。(add to)", "answers": ["I don’t want to add to your troubles."], "explanation": "want to do；add to 增加。"}, {"id": "W2V-6", "number": 6, "prompt": "我们希望在不久的将来移居乡下。(in the near future)", "answers": ["We hope to move to the country in the near future."], "explanation": "hope to do；country 在此为乡下。"}, {"id": "W2V-7", "number": 7, "prompt": "首先你要将你需要学习的东西列一个清单。(make a list)", "answers": ["First you should make a list of the things you need to learn."], "explanation": "the things 后定语从句省略作宾语的 that。"}, {"id": "W2V-8", "number": 8, "prompt": "因脚趾受伤，他不能参加今天的篮球赛了。(take part in)", "answers": ["Because his toes are hurt, he is unable to take part in today’s basketball game."], "explanation": "because 表原因；be unable to do 无法做。"}, {"id": "W2V-9", "number": 9, "prompt": "如果你继续和那群坏孩子闲逛，你考试会不及格的。(hang out)", "answers": ["If you continue to hang out with that group of bad boys, you’ll fail in your exams."], "explanation": "条件从句一般现在时，主句将来时；hang out with 和……闲逛。"}, {"id": "W2V-10", "number": 10, "prompt": "关心学生的学习是教师分内的事。(be concerned about)", "answers": ["It’s a teacher’s duty to be concerned about the students’ study."], "explanation": "It 为形式主语，不定式为真正主语；be concerned about 关心。"}], "passage": ""}, {"id": "W2A", "part": 2, "page": "27", "title": "提升Ⅰ · 阅读理解", "source": "五三 p.27 · 提升Ⅰ · 阅读理解", "kind": "choice", "questions": [{"id": "W2A-1", "number": 1, "prompt": "What is implied in the first paragraph?", "answers": ["B"], "explanation": "公共场所的接触会传播细菌，因此可推断脏手可能留下细菌；A 的 free from diseases 过于绝对。", "options": ["Washing hands regularly may free you from diseases.", "Dirty hands may leave bacteria in public places.", "Reading in libraries is not advised due to bacteria.", "Sharing computers is not recommended now."]}, {"id": "W2A-2", "number": 2, "prompt": "What is the RIGHT order of proper hand-washing? a. Turn on the faucet and wet the hands. b. Dry the hands with a clean towel and turn off the tap. c. Apply some soap to the hands and rub the hands completely. d. Wash the hands under running water and wash them downwards.", "answers": ["D"], "explanation": "依据第二至四段：湿手 a → 涂皂揉搓 c → 流水冲洗 d → 擦干关水 b。", "options": ["abcd", "adcb", "acbd", "acdb"]}, {"id": "W2A-3", "number": 3, "prompt": "What can we know about washing hands with hand sanitizers according to the passage?", "answers": ["C"], "explanation": "末段指出不含酒精的部分产品不推荐，故按原文选 C；其余选项没有依据或过度概括。", "options": ["About half a teaspoon of sanitizer is enough.", "For dirty hands, hand sanitizers are useless.", "Only the alcohol-based ones should be used.", "Hand sanitizers can wash off bacteria completely."]}, {"id": "W2A-4", "number": 4, "prompt": "What’s the possible title for the passage?", "answers": ["A"], "explanation": "主体逐步介绍正确洗手方法，A 最贴合全文；其余标题过宽或偏离重点。", "options": ["Proper hand-washing skills", "Frequent washing kills viruses", "The best way to prevent bacteria", "Ways to avoid spread of infection"]}], "passage": "Most of the diseases are caused by bacteria on the hands. 99% of the spread of bacteria traveling through droplets can be prevented by proper hand-washing. Bacteria can be picked up while using public restrooms, reading in libraries and sharing computers, etc. Every individual needs to wash his or her hands properly to reduce disease spread.\n\nTurn on the tap and let running water wet the hands and wrists. While using a public restroom, one should consider that the faucets (水龙头) might have been polluted. Thus one should turn on the tap by using a paper towel. Apply some soap to the hands. Soaps work well to remove the dirt.\n\nFor at least 15 seconds rub (搓) the hands strongly together, which, along with the soap and water, helps wash off bacteria. Rub the hands thoroughly, including the back of the hands, between the fingers, around the surfaces and under the fingernails and wrists.\n\nUnder running water, wash the hands well. The running water carries away the dirt from the hands. While washing the fingers, allow the water to drop downwards instead of moving towards the elbows and polluting them. With a clean towel, dry the hands. If using a public restroom, a paper towel should be used to turn the faucet off.\n\nWhen soap and water are not available, the alcohol-based hand sanitizer (消毒杀菌剂) proves to be an excellent alternative. In fact, this hand sanitizer is more effective in killing viruses and bacteria, compared with soap and water, which only wash them off. Hand sanitizers can help prevent skin dryness, but some of them may lack alcohol content and are therefore not recommended. Washing the hands with the sanitizer simply requires rubbing the hands together till the hands are dry. The hand sanitizer should cover all the surfaces of the hands."}, {"id": "W2GAP", "part": 2, "page": "27—28", "title": "提升Ⅱ · 七选五", "source": "五三 p.27—28 · 提升Ⅱ · 七选五", "kind": "gap", "questions": [{"id": "W2GAP-1", "number": 1, "prompt": "第1空", "answers": ["C"], "explanation": "玩手机、看电视都指看屏幕；C 概括这些现象，承接前文。", "options": ["They slowed down their lives.", "Technology sometimes goes wrong, though.", "Most are probably looking at some kind of screen.", "We think technology helps us connect with other people.", "This gives you a chance to be able to exercise physically.", "You never know it may be the only thing that you need.", "We all agree that modern technology has taken over our lives, for good of course."]}, {"id": "W2GAP-2", "number": 2, "prompt": "第2空", "answers": ["A"], "explanation": "过去每周休息、不使用科技，意味着放慢生活节奏；They 指过去的人。", "options": ["They slowed down their lives.", "Technology sometimes goes wrong, though.", "Most are probably looking at some kind of screen.", "We think technology helps us connect with other people.", "This gives you a chance to be able to exercise physically.", "You never know it may be the only thing that you need.", "We all agree that modern technology has taken over our lives, for good of course."]}, {"id": "W2GAP-3", "number": 3, "prompt": "第3空", "answers": ["E"], "explanation": "后文列举徒步、慢跑、登山，E 引出运动机会，This 指停止使用科技。", "options": ["They slowed down their lives.", "Technology sometimes goes wrong, though.", "Most are probably looking at some kind of screen.", "We think technology helps us connect with other people.", "This gives you a chance to be able to exercise physically.", "You never know it may be the only thing that you need.", "We all agree that modern technology has taken over our lives, for good of course."]}, {"id": "W2GAP-4", "number": 4, "prompt": "第4空", "answers": ["D"], "explanation": "后句 However 说拔掉电源后联系更紧密；D 的科技帮助联系构成转折。", "options": ["They slowed down their lives.", "Technology sometimes goes wrong, though.", "Most are probably looking at some kind of screen.", "We think technology helps us connect with other people.", "This gives you a chance to be able to exercise physically.", "You never know it may be the only thing that you need.", "We all agree that modern technology has taken over our lives, for good of course."]}, {"id": "W2GAP-5", "number": 5, "prompt": "第5空", "answers": ["F"], "explanation": "F 中 it 指 unplugging technology；后文解释它让人更健康、快乐和善于交往。", "options": ["They slowed down their lives.", "Technology sometimes goes wrong, though.", "Most are probably looking at some kind of screen.", "We think technology helps us connect with other people.", "This gives you a chance to be able to exercise physically.", "You never know it may be the only thing that you need.", "We all agree that modern technology has taken over our lives, for good of course."]}], "passage": "Take a second and look at the people around you. What are they doing? Some are playing with their phones. Some are watching TV. [1] We never take a rest from these technologies.\n\nIn the past, people took one regular rest day every week. They did no big activities and used no technology. [2]\n\nExperts hope we can do this again. They want us to promise to unplug technology. Without the use of technology, there will be no sitting down and staring at the screen. [3] Take a hike with your friends, run or jog with your dog or climb a mountain. Not only will this make you healthier and get your body moving, but this also makes you lose the extra unhealthy fat. You get to have real exercise and a hot body.\n\n[4] However, when we unplug it, we connect with one another even more. We stop focusing on media and start focusing on our real relationships and all of those important real-life connections with the special people in our life. By unplugging technology and devoting more time to the important people in our life, we are on our way to find more happiness. Please remember: relationships are one of the leading contributors to a healthy and happy life.\n\nTry unplugging technology once in a while and give yourself a break and some relaxation. You deserve it. [5] Because of the absence of technology, you get to become healthier, happier and more sociable. Unplugging is hard at first, but it gets easier. Maybe you’ll like it—especially when you start having special moments with your family.", "bank": ["They slowed down their lives.", "Technology sometimes goes wrong, though.", "Most are probably looking at some kind of screen.", "We think technology helps us connect with other people.", "This gives you a chance to be able to exercise physically.", "You never know it may be the only thing that you need.", "We all agree that modern technology has taken over our lives, for good of course."]}, {"id": "W2CLOZE", "part": 2, "page": "28", "title": "提升Ⅲ · 完形填空", "source": "五三 p.28 · 提升Ⅲ · 完形填空", "kind": "choice", "questions": [{"id": "W2CLOZE-1", "number": 1, "prompt": "第1空", "answers": ["A"], "explanation": "look at 看向；watch 通常直接接宾语，不能在这里接 at。", "options": ["looked", "watched", "found", "stepped"]}, {"id": "W2CLOZE-2", "number": 2, "prompt": "第2空", "answers": ["D"], "explanation": "hope to do 希望做；look forward to 后要接动名词。", "options": ["failing", "looking forward", "succeeding", "hoping"]}, {"id": "W2CLOZE-3", "number": 3, "prompt": "第3空", "answers": ["B"], "explanation": "两千多英里的旅程，结合父母前来观赛，driven（开车）最合理。", "options": ["bicycled", "driven", "run", "walked"]}, {"id": "W2CLOZE-4", "number": 4, "prompt": "第4空", "answers": ["D"], "explanation": "Albert 和 Doris 为父母，Peggy 是他们的女儿。", "options": ["friend", "children", "son", "daughter"]}, {"id": "W2CLOZE-5", "number": 5, "prompt": "第5空", "answers": ["A"], "explanation": "音乐开始，Peggy 随即滑上冰面，started 符合时序。", "options": ["started", "played", "developed", "sang"]}, {"id": "W2CLOZE-6", "number": 6, "prompt": "第6空", "answers": ["B"], "explanation": "belief in herself 表示对自己的信心；下文恐惧消失与之呼应。", "options": ["thought", "belief", "success", "design"]}, {"id": "W2CLOZE-7", "number": 7, "prompt": "第7空", "answers": ["D"], "explanation": "充满信心，原先的恐惧消失；be gone 表消失。", "options": ["lost", "present", "strong", "gone"]}, {"id": "W2CLOZE-8", "number": 8, "prompt": "第8空", "answers": ["A"], "explanation": "上文 letting the music carry her 明确指音乐，music 与之照应。", "options": ["music", "fear", "ice", "audience"]}, {"id": "W2CLOZE-9", "number": 9, "prompt": "第9空", "answers": ["D"], "explanation": "滑行、跳跃、最后转身依次进行，用 then。", "options": ["so", "or", "before", "then"]}, {"id": "W2CLOZE-10", "number": 10, "prompt": "第10空", "answers": ["A"], "explanation": "one of the other skaters 指其他参赛滑冰者之一。", "options": ["skaters", "parents", "judges", "spectators"]}, {"id": "W2CLOZE-11", "number": 11, "prompt": "第11空", "answers": ["C"], "explanation": "观众和选手称赞后，转而关注决定分数的裁判 judges。", "options": ["players", "audience", "judges", "parents"]}, {"id": "W2CLOZE-12", "number": 12, "prompt": "第12空", "answers": ["A"], "explanation": "wait for the score 等待分数；其他选项搭配或意义不合。", "options": ["waited", "looked", "wished", "asked"]}, {"id": "W2CLOZE-13", "number": 13, "prompt": "第13空", "answers": ["D"], "explanation": "等比赛结果时心情紧张，anxiously 焦虑地。", "options": ["comfortably", "hurriedly", "happily", "anxiously"]}, {"id": "W2CLOZE-14", "number": 14, "prompt": "第14空", "answers": ["C"], "explanation": "results were announced 比赛结果被宣布。", "options": ["cried out", "let out", "announced", "indicated"]}, {"id": "W2CLOZE-15", "number": 15, "prompt": "第15空", "answers": ["D"], "explanation": "首段交代来自 California，结尾地点与之呼应。", "options": ["England", "Cleveland", "Ohio", "California"]}], "passage": "As she waited at the edge of the ice for her music to start, Peggy took a quick look at her father standing nearby with a group of parents and teachers. He smiled at her. Then she [1] at the audience, [2] to see her mother. These two, Albert and Doris Fleming, had [3] all the way from California more than 2,000 miles away, to see their [4] compete in this sports meet in Cleveland, Ohio.\n\nThe music [5] and Peggy moved onto the ice, letting the music carry her along into her turns, and she began skating with much [6] in herself. The fear she always had in the last seconds before skating onto the ice was [7]. She was feeling the movement of the [8] and letting it carry her. She skated easily, [9] did some jumps and a final turn and her performance was finished.\n\nThe crowd loved it and cheered as she skated off the ice. “Nice job,” said one of the other [10]. It was the remark that always came after a free-skating performance. But what should the [11] say? Standing beside her father, Peggy [12] for the score. On all sides were other young skaters, some waiting [13] alone, others with a parent. Shortly before 10 o’clock the results were [14]. The new United States Women’s Figure Skating Champion was Peggy Fleming of Pasadena, [15]."}, {"id": "W3I", "part": 3, "page": "29", "title": "基础Ⅰ · 单词拼写", "source": "五三 p.29 · 基础Ⅰ · 单词拼写", "kind": "fill", "questions": [{"id": "W3I-1", "number": 1, "prompt": "I didn’t h___ for a moment about taking the job.", "answers": ["hesitate"], "explanation": "didn’t 后用动词原形；hesitate about 对……犹豫。"}, {"id": "W3I-2", "number": 2, "prompt": "We can’t ___ (准许进入) her into the army because she is young.", "answers": ["admit"], "explanation": "can’t 后用 admit；admit ... into 准许加入。"}, {"id": "W3I-3", "number": 3, "prompt": "C___ is a kind of bird with very long legs and neck.", "answers": ["Crane"], "explanation": "长腿长颈的鸟是 crane（鹤）；按题面填写 Crane。"}, {"id": "W3I-4", "number": 4, "prompt": "The farmer’s r___ crows every morning when the sun rises.", "answers": ["rooster"], "explanation": "crows 提示公鸡 rooster。"}, {"id": "W3I-5", "number": 5, "prompt": "People live longer ___ (现在), and they are better educated.", "answers": ["nowadays"], "explanation": "nowadays 为时间副词。"}, {"id": "W3I-6", "number": 6, "prompt": "The dog has transferred its affection to its new ___ (主人).", "answers": ["master"], "explanation": "its new 后接名词 master。"}, {"id": "W3I-7", "number": 7, "prompt": "She knew that the girls used to ___ (模仿) her and laugh at her behind her back.", "answers": ["imitate"], "explanation": "used to 后用原形 imitate。"}, {"id": "W3I-8", "number": 8, "prompt": "The diver flipped over ___ (向后) into the water.", "answers": ["backwards", "backward"], "explanation": "副词 backwards 修饰 flipped；backward 也可作副词。"}, {"id": "W3I-9", "number": 9, "prompt": "Most plants will r___ in about six to eight weeks.", "answers": ["root"], "explanation": "will 后接原形 root，意为生根。"}], "passage": ""}, {"id": "W3II", "part": 3, "page": "29", "title": "基础Ⅱ · 短语填空", "source": "五三 p.29 · 基础Ⅱ · 短语填空", "kind": "fill", "questions": [{"id": "W3II-1", "number": 1, "prompt": "It took an extraordinary effort to ___ preparing his classes or correcting his students’ homework.", "answers": ["focus on"], "explanation": "focus on 后接动名词，表示集中精力。"}, {"id": "W3II-2", "number": 2, "prompt": "Many new changes will be ___ in China’s industry.", "answers": ["brought about"], "explanation": "will be 后接过去分词；bring about 引起。"}, {"id": "W3II-3", "number": 3, "prompt": "It must ___ and grow with their feelings, thoughts, and desires.", "answers": ["be rooted in"], "explanation": "must 后用 be；be rooted in 根植于。"}, {"id": "W3II-4", "number": 4, "prompt": "Many pictures ___ simple geometric designs.", "answers": ["are based on"], "explanation": "pictures 为复数；be based on 以……为基础。"}, {"id": "W3II-5", "number": 5, "prompt": "They ___ the attempt in despair.", "answers": ["gave up"], "explanation": "放弃尝试，按语境及参考答案用过去式 gave up。"}, {"id": "W3II-6", "number": 6, "prompt": "___ you can’t find anybody here; they’re all away at a meeting.", "answers": ["No wonder"], "explanation": "No wonder 难怪，后接结果。"}, {"id": "W3II-7", "number": 7, "prompt": "I need to ___ who tried to frame me.", "answers": ["find out"], "explanation": "find out 查明；who 从句作宾语。"}, {"id": "W3II-8", "number": 8, "prompt": "The team should be ___ before the project starts.", "answers": ["put together"], "explanation": "should be＋过去分词；put together 组建。"}], "passage": "", "bank": "no wonder; be based on; focus on; be rooted in; bring about; give up; find out; put together"}, {"id": "W3III", "part": 3, "page": "29", "title": "基础Ⅲ · 单句语法填空", "source": "五三 p.29 · 基础Ⅲ · 单句语法填空", "kind": "fill", "questions": [{"id": "W3III-1", "number": 1, "prompt": "The great majority of players would, of course, sign the contract without ___ (hesitate).", "answers": ["hesitation"], "explanation": "without 后用名词；without hesitation 毫不犹豫。"}, {"id": "W3III-2", "number": 2, "prompt": "He had an ___ (inspire): he’d give her a dog for her birthday.", "answers": ["inspiration"], "explanation": "an 后接名词 inspiration，此处指一个好主意。"}, {"id": "W3III-3", "number": 3, "prompt": "He had the ___ (satisfy) of seeing his book become a best-seller.", "answers": ["satisfaction"], "explanation": "the 后接名词 satisfaction。"}, {"id": "W3III-4", "number": 4, "prompt": "We don’t have to envy anyone else, because our ___ (exist) is unique.", "answers": ["existence"], "explanation": "our 后接名词 existence，作主语。"}, {"id": "W3III-5", "number": 5, "prompt": "The air was so cold that we could hardly ___ (breath).", "answers": ["breathe"], "explanation": "could 后需动词原形 breathe，注意词尾 e。"}, {"id": "W3III-6", "number": 6, "prompt": "Muscular ___ (ache) and pains can be soothed by a relaxing massage.", "answers": ["aches"], "explanation": "与 pains 并列，名词 ache 用复数。"}], "passage": ""}, {"id": "W3IV", "part": 3, "page": "29—30", "title": "基础Ⅳ · 完成句子", "source": "五三 p.29—30 · 基础Ⅳ · 完成句子", "kind": "fill", "questions": [{"id": "W3IV-1", "number": 1, "prompt": "他们参观了这所学校，还参观了一些工厂和医院。They visited the school ___ some factories and hospitals.", "answers": ["as well as"], "explanation": "as well as 以及、还。"}, {"id": "W3IV-2", "number": 2, "prompt": "您可以从数据库的现有用户中进行查找和选择。You can ___ from existing users in the database.", "answers": ["look up and select"], "explanation": "can 后两个并列动词用原形。"}, {"id": "W3IV-3", "number": 3, "prompt": "他做了彻底的调查，怪不得他对此事了解得那么多。He had made a thorough investigation. ___ he knew so much about it.", "answers": ["No wonder"], "explanation": "前句为原因，No wonder 引出可以理解的结果。"}, {"id": "W3IV-4", "number": 4, "prompt": "该报道基于不准确的信息。The report ___ inaccurate information.", "answers": ["is based on"], "explanation": "report 单数；be based on 基于。"}, {"id": "W3IV-5", "number": 5, "prompt": "会谈将聚焦该地区的经济发展。The talks will ___ the economic development of the region.", "answers": ["focus on"], "explanation": "will 后原形；focus on 聚焦。"}, {"id": "W3IV-6", "number": 6, "prompt": "这次危机的根源在于两个集团间的严重对立。The crisis ___ deep rivalries between the two groups.", "answers": ["is rooted in"], "explanation": "be rooted in 根源在于；crisis 为单数。"}, {"id": "W3IV-7", "number": 7, "prompt": "你为什么不能同她和解并忘掉你们吵架的事呢？Why don’t you ___ and forget all about your quarrel?", "answers": ["make up with her"], "explanation": "make up with sb. 与某人和解，不同于 make up for 弥补。"}, {"id": "W3IV-8", "number": 8, "prompt": "特大的春雨造成了这场水灾。The heavy spring rain ___ the flood.", "answers": ["brought about"], "explanation": "bring about 导致，过去式 brought。"}, {"id": "W3IV-9", "number": 9, "prompt": "他一点一点地把它拆开，然后又把它组合起来。He took it apart bit by bit, and ___ again.", "answers": ["put it back together"], "explanation": "put ... back together 重新组装；put 为过去式。"}, {"id": "W3IV-10", "number": 10, "prompt": "我建议他好好休息一下。I suggested ___.", "answers": ["he have a good rest"], "explanation": "suggest 表建议，宾语从句用 (should)＋原形；按五个空填 he have a good rest。"}], "passage": ""}, {"id": "W3V", "part": 3, "page": "30", "title": "基础Ⅴ · 翻译句子", "source": "五三 p.30 · 基础Ⅴ · 翻译句子", "kind": "manual", "questions": [{"id": "W3V-1", "number": 1, "prompt": "你心不在焉的，难怪你对演讲一无所知。(no wonder)", "answers": ["As you were absent-minded, it’s no wonder that you know nothing about the speech."], "explanation": "as 引导原因；it’s no wonder that 难怪；know nothing about 对……一无所知。"}, {"id": "W3V-2", "number": 2, "prompt": "据说，这种疾病在美国重新出现了。(be said to)", "answers": ["The disease is said to have appeared again in the USA."], "explanation": "be said to have done 表动作先于被报道的时间已发生。"}, {"id": "W3V-3", "number": 3, "prompt": "这样的一种观点引起了很大的分歧是不足为奇的。(it 作形式主语)", "answers": ["It is not surprising that such a view has led to very considerable conflict."], "explanation": "It 形式主语，that 从句是真正主语；lead to 引起。"}, {"id": "W3V-4", "number": 4, "prompt": "那天是父亲的生日，我不由自主地想起了他。(find)", "answers": ["It was Dad’s birthday, and I found myself thinking of him."], "explanation": "find＋宾语＋现在分词，表示发现自己正做某事。"}, {"id": "W3V-5", "number": 5, "prompt": "他不能回答这个问题，她也不能。(倒装语序)", "answers": ["He can’t answer this question, and neither can she."], "explanation": "否定附和用 neither＋助动词/情态动词＋主语。"}, {"id": "W3V-6", "number": 6, "prompt": "如果你想参加这个项目，你必须尽快报名。(sign up)", "answers": ["If you want to take part in the project, you must sign up as soon as possible."], "explanation": "sign up 报名；as soon as possible 尽快。"}, {"id": "W3V-7", "number": 7, "prompt": "最后但同样重要的是，我希望能够有更多的时间与家人和朋友在一起。(last but not least)", "answers": ["Last but not least, I hope to be able to have more time to spend with my family and friends."], "explanation": "last but not least 作篇章连接；time to spend 为不定式后置修饰。"}, {"id": "W3V-8", "number": 8, "prompt": "如果我处在你的位置上，我或许也会像你这么做。(in one’s position)", "answers": ["Were I in your position, I might do the same as you."], "explanation": "虚拟条件句省略 if 时 were 提前；主句 might＋原形。"}, {"id": "W3V-9", "number": 9, "prompt": "我会把所有事实都告诉你，以便你可以自己做出判断。(so that 引导目的状语从句)", "answers": ["I’ll tell you all the facts so that you can judge by yourself."], "explanation": "so that 引出目的，常与 can 等情态动词连用。"}, {"id": "W3V-10", "number": 10, "prompt": "你能否向我解释一下你迟到的原因？(why 引导定语从句)", "answers": ["Can you explain to me the reason why you are late?"], "explanation": "the reason 后 why 作原因状语；explain sth. to sb.。"}, {"id": "W3V-11", "number": 11, "prompt": "他还记得当他自己也像那样工作的那段时间。(when 引导定语从句)", "answers": ["He could remember a time when he had worked like that himself."], "explanation": "a time 为先行词，when 在从句中作时间状语。"}, {"id": "W3V-12", "number": 12, "prompt": "爆炸的地方被警察封锁起来了。(where 引导定语从句)", "answers": ["The area where the explosion occurred was closed off by the police."], "explanation": "where 引导定语从句修饰 area；主句被动 was closed off。"}], "passage": ""}, {"id": "W3VI", "part": 3, "page": "30", "title": "基础Ⅵ · 课文语法填空", "source": "五三 p.30 · 基础Ⅵ · 课文语法填空", "kind": "fill", "questions": [{"id": "W3VI-1", "number": 1, "prompt": "第1空 (believe)", "answers": ["believed"], "explanation": "结合 hesitated 和叙事语境，使用一般过去时。"}, {"id": "W3VI-2", "number": 2, "prompt": "第2空 (amaze)", "answers": ["amazing"], "explanation": "描述太极令人惊叹，用 amazing；amazed 描述人的感受。"}, {"id": "W3VI-3", "number": 3, "prompt": "第3空", "answers": ["It"], "explanation": "It is said that 据说，It 为形式主语。"}, {"id": "W3VI-4", "number": 4, "prompt": "第4空 (inspire)", "answers": ["inspiration"], "explanation": "draw inspiration from 从……获得灵感；此处为不可数名词。"}, {"id": "W3VI-5", "number": 5, "prompt": "第5空", "answers": ["after"], "explanation": "name after 以……命名。"}, {"id": "W3VI-6", "number": 6, "prompt": "第6空 (learn)", "answers": ["learning"], "explanation": "While I was learning 的省略形式，主语与主句一致。"}, {"id": "W3VI-7", "number": 7, "prompt": "第7空 (muscle)", "answers": ["muscles"], "explanation": "指多块肌肉，用复数。"}, {"id": "W3VI-8", "number": 8, "prompt": "第8空 (slow)", "answers": ["slowly"], "explanation": "修饰 improved，用副词 slowly。"}, {"id": "W3VI-9", "number": 9, "prompt": "第9空", "answers": ["in"], "explanation": "be rooted in 根植于。"}, {"id": "W3VI-10", "number": 10, "prompt": "第10空 (happy)", "answers": ["happier"], "explanation": "与 more confident 并列，用比较级。"}], "passage": "I hesitated to join the new Tai Chi Club because I always [1] (believe) tai chi was for old people. In fact, it was really [2] (amaze) and had a huge effect on me physically and mentally. [3] is said that a 13th-century Taoist named Zhang Sanfeng invented tai chi after drawing [4] (inspire) from a fight between a snake and a bird. Chinese martial arts have a long-standing practice of imitating animals. Therefore, it is not surprising that some tai chi moves are named [5] animals.\n\nWhile [6] (learn) the basics of tai chi, I found myself bored and aching. Luckily, my coach taught me how to relax my [7] (muscle) and focus on peace of mind. With this requirement, I found to my satisfaction that my balance and flexibility [8] (slow) improved and that my love for tai chi returned stronger than ever.\n\nI discovered that tai chi is deeply rooted [9] the Chinese philosophy of yin and yang, and the practice of tai chi aims to maintain the balance of yin and yang in the body.\n\nA year of practising tai chi has had a positive effect on my everyday life. I feel [10] (happy) and more confident. I will continue to practise tai chi and enjoy the benefits it has brought me."}, {"id": "W3A", "part": 3, "page": "31", "title": "提升Ⅰ · 阅读理解 A", "source": "五三 p.31 · 提升Ⅰ · 阅读理解 A", "kind": "choice", "questions": [{"id": "W3A-1", "number": 1, "prompt": "How did the author feel after the car accident?", "answers": ["C"], "explanation": "第四段说保持坚强是唯一选择，并决定充实生活，体现积极态度；并非抱怨或无法接受。", "options": ["She complained that life was unfair to her.", "She was unable to accept the loss of her leg.", "She kept a positive attitude toward life.", "She felt lucky that she was still alive."]}, {"id": "W3A-2", "number": 2, "prompt": "Why did the author feel happy in Paragraph 3?", "answers": ["A"], "explanation": "她将假肢捐给买不起的护士，帮助别人带来的快乐更大。", "options": ["She was able to offer help to others.", "She could wear her false leg again.", "She had lived her life to the fullest.", "She could do everyday things the same as everybody else."]}, {"id": "W3A-3", "number": 3, "prompt": "Why did the author begin modeling in 2014?", "answers": ["B"], "explanation": "末段梦想是激励人相信自己的美，与鼓励他人自信一致；不是追求名气。", "options": ["She wanted to be a famous magazine star.", "She wanted to encourage others to be confident in themselves.", "She wanted to challenge herself to be a speaker.", "She wanted to prove that disabled people could also succeed."]}, {"id": "W3A-4", "number": 4, "prompt": "What was the author’s main purpose in writing the article?", "answers": ["C"], "explanation": "作者通过个人经历传递自信，末句 inspire 点明写作目的。", "options": ["To stress the importance of having a dream.", "To show how difficult the life is for disabled people.", "To inspire others by sharing her past experiences.", "To give advice to disabled people on how to make a living."]}], "passage": "On the night of August 24, 2001, everything changed when my friend’s car hit a wall with me inside. I lost most of my right leg, and I was left bleeding with several broken bones. At the hospital, although my body was weak, my mind was still very clear. I just kept telling myself to hold on. A week later, I made a deal with the doctors that once I could roll onto my side, I could leave. Two weeks later, I was allowed to go home.\n\nAlthough I left the hospital, the fight was far from over. My left knee was badly injured, which resulted in different operations over the next few years.\n\nAnd soon, more of my right leg had to be removed. This made it harder to wear my false leg, so I donated it to a nurse who couldn’t afford one for herself. The joy of being able to provide this gift for someone else was greater than the happiness I felt on any day that I was able to wear it myself.\n\nPeople often tell me they’re proud of me for staying strong. But in my mind, staying strong has always been my only choice. So, on the day I left the hospital, I made a promise to myself to always live life to the fullest. Now, I may not be able to do things the way everybody else does them, but still, I always find a way to do them. I soon settled into everyday life again, until one day I realized I wasn’t living my life as fully as I wanted to.\n\nAfter 13 years of thinking that I was confident, I had an unfamiliar feeling that swept over me. For the first time in my life, I was not only confident but I wanted to help those around me.\n\nIn 2014, I even started modeling. My dream is that one day a little girl will see me in a magazine and say, “Wow, she’s beautiful, and she only has one leg. I can do that too someday, even though I have a disability.” My dream is simple: to inspire every man, woman, and child to know and believe that they are beautiful just the way they are."}, {"id": "W3B", "part": 3, "page": "31—32", "title": "提升Ⅰ · 阅读理解 B", "source": "五三 p.31—32 · 提升Ⅰ · 阅读理解 B", "kind": "choice", "questions": [{"id": "W3B-5", "number": 5, "prompt": "Why does the author mention his son in the first two paragraphs?", "answers": ["C"], "explanation": "借儿子羡慕父辈童年引出孩子缺少冒险机会的问题，服务全文论点。", "options": ["To praise his son for wanting to live in the 1970s and 1980s.", "To introduce the kid’s wish that could not come true forever.", "To introduce the problem of kids’ lack of chances to take a risk.", "To encourage kids to own the most advanced cellphones."]}, {"id": "W3B-6", "number": 6, "prompt": "If nowadays a 14-year-old boy wants to jump off the bridge into the river, what will happen?", "answers": ["C"], "explanation": "第四段说有好心成年人会 call the cops，按作者设想孩子会被警察制止。", "options": ["He can swim freely and happily.", "He will be warned of danger.", "He will be forbidden by the police.", "He will injure himself seriously."]}, {"id": "W3B-7", "number": 7, "prompt": "What does the author advise allowing kids to do?", "answers": ["B"], "explanation": "倒数第二段强调在成年人监督下做事；B 有父母在场，其他选项都强调独自冒险。", "options": ["To swim alone in the deep river.", "To do some housework with their parents.", "To cut paper with sharp scissors alone.", "To jump off the bridge into the river alone."]}, {"id": "W3B-8", "number": 8, "prompt": "Who are the aimed readers of this passage?", "answers": ["D"], "explanation": "文中 Allow your child、encourage and praise your child’s ... 直接面向父母。", "options": ["Teachers.", "Kids.", "Passers-by.", "Parents."]}], "passage": "“I wish I grew up back in Dad’s childhood.” My 14-year-old son has an iPhone that’s newer than mine, an Xbox, and instant access to friends, entertainment and nearly all human knowledge via the Internet. But he wishes he grew up in the 1970s and 1980s.\n\n“How come?” I asked, and my son’s answer involved freedom, autonomy (自主), risk and over-involvement of adults in kids’ lives.\n\nMy son has heard my stories of summer days at the river with friends. We’d jump off the wooden bridge into the water below. My son lives just a few blocks from that same exact river and the same exact bridge.\n\nThe town hasn’t changed. Time has. My son knows that if he and his friends attempted to jump off the bridge and swim—as his dad did, many times—the most likely outcome (结果) is that some well-meaning adult would call the cops.\n\nAt 14—an age at which, in generations past, most boys were contributing to the well-being of their families by working—my son is ready, able and willing to put his skills and strength to the tests in the real world. Yet he, like so many other American boys and girls, is stymied (阻挠) by a culture that seems to have elevated safety to the highest regard.\n\nLet kids try some risky things—cutting the lawn, using tools and sharp knives, starting a fire, cooking—under the supervision of an adult who models and discusses safety protocols. Allow your child to gradually assume more responsibility, and a child who helps prepare and cook meals will be better prepared to cook independently.\n\nAbove all, encourage and praise your child’s ambition and determination."}, {"id": "W3GRAM", "part": 3, "page": "32", "title": "提升Ⅱ · 语法填空", "source": "五三 p.32 · 提升Ⅱ · 语法填空", "kind": "fill", "questions": [{"id": "W3GRAM-1", "number": 1, "prompt": "第1空 (show)", "answers": ["shows"], "explanation": "one of＋最高级＋可数名词复数。"}, {"id": "W3GRAM-2", "number": 2, "prompt": "第2空 (see)", "answers": ["be seen"], "explanation": "can 后用 be＋过去分词，gardens 是被看见的。"}, {"id": "W3GRAM-3", "number": 3, "prompt": "第3空 (design)", "answers": ["designing"], "explanation": "be busy doing 忙于做某事。"}, {"id": "W3GRAM-4", "number": 4, "prompt": "第4空", "answers": ["that", "which"], "explanation": "定语从句修饰 land，关系代词在从句中作主语。"}, {"id": "W3GRAM-5", "number": 5, "prompt": "第5空 (include)", "answers": ["includes"], "explanation": "动名词短语 helping parents with housework 作单数主语，描述习惯用一般现在时。"}, {"id": "W3GRAM-6", "number": 6, "prompt": "第6空 (help)", "answers": ["to help"], "explanation": "ask sb. to do sth. 要求某人做某事。"}, {"id": "W3GRAM-7", "number": 7, "prompt": "第7空 (compare)", "answers": ["Compared"], "explanation": "compared with 与……相比，过去分词短语作状语。"}, {"id": "W3GRAM-8", "number": 8, "prompt": "第8空", "answers": ["a"], "explanation": "activity 单数可数，泛指一项喜爱的活动用 a。"}, {"id": "W3GRAM-9", "number": 9, "prompt": "第9空 (color)", "answers": ["colorful", "colourful"], "explanation": "形容词修饰 flower，接受美式 colorful 和英式 colourful。"}, {"id": "W3GRAM-10", "number": 10, "prompt": "第10空 (patient)", "answers": ["patience"], "explanation": "与 devotion 并列作 skills 的具体说明，用名词 patience。"}], "passage": "Every spring, London hosts the Chelsea Flower Show. It is one of the most popular garden and flower [1] (show) in the world. People show off their creativity with trees and flowers. Gardens of different shapes and styles can [2] (see) during the show time.\n\nThe British people like gardening. Up and down the country, people are busy [3] (design) their gardens. If a home doesn’t have a garden, people will rent a piece of land [4] is used for gardening and growing fruit and vegetables.\n\nYou don’t have to be good at gardening. Even kids can do it. Actually in Britain, helping parents with housework [5] (include) the garden.\n\nMy dad was a master of gardening. He often asked me [6] (help) him with the outdoor tasks. He would mow the lawn (修剪草坪) while I would water our trees and plants.\n\n[7] (compare) with indoor housework, gardening is cheerful and relaxing. The smooth sounds of water, wind and singing birds make gardening [8] favorite activity. You feel pride as you see a small seed grow into a soft, [9] (color) flower. Also, gardening teaches us two useful skills in life: [10] (patient) and devotion."}];
